import { ScrollArea } from '@absoluteui/components/scroll-area';

const notes = document.createElement('div');
for (let i = 1; i <= 30; i++) {
  const item = document.createElement('p');
  item.textContent = `Release 1.${String(i)}: improvements and fixes.`;
  notes.append(item);
}
document.body.append(notes);
ScrollArea.enhance(notes, { label: 'Release notes', maxBlockSize: '12rem' });

import { ScrollArea } from '@absoluteui/components/scroll-area';
import { Badge } from '@absoluteui/components/badge';

const strip = document.createElement('div');
strip.style.display = 'flex';
strip.style.gap = '0.5rem';
for (const label of ['Design', 'Engineering', 'Finance', 'Legal', 'Marketing', 'Operations', 'People', 'Product', 'Sales', 'Support']) {
  const host = document.createElement('span');
  strip.append(host);
  Badge.create(host, { label, variant: 'outline' });
}
document.body.append(strip);
ScrollArea.enhance(strip, { label: 'Departments', orientation: 'horizontal' });
